<template>
  <a-card title="图库">
    <a-space wrap class="toolbar"><a-input-search v-model:value="keyword" placeholder="搜索图片名称" @search="load" />
      <a-select v-model:value="alpha" allow-clear placeholder="透明通道" style="width:120px" @change="load"><a-select-option value="true">有透明像素</a-select-option><a-select-option value="false">不透明</a-select-option></a-select>
      <a-button @click="selectPage">本页全选</a-button><a-button @click="selected=[]">清空选择</a-button><span>已选 {{ selected.length }} 张</span>
      <a-upload multiple :show-upload-list="false" :before-upload="stageUpload"><a-button type="primary">选择上传图片</a-button></a-upload><a-button :disabled="!uploads.length" @click="upload">上传队列 {{ uploads.length }}</a-button>
    </a-space>
    <a-space wrap class="toolbar"><a-select v-model:value="transform.size" style="width:120px" @change="setSize"><a-select-option value="64">64×64</a-select-option><a-select-option value="128">128×128</a-select-option><a-select-option value="256">256×256</a-select-option><a-select-option value="512">512×512</a-select-option><a-select-option value="custom">自定义</a-select-option></a-select>
      <a-input-number v-if="transform.size==='custom'" v-model:value="transform.width" :min="1" :max="8192" placeholder="宽" /><a-input-number v-if="transform.size==='custom'" v-model:value="transform.height" :min="1" :max="8192" placeholder="高" />
      <a-select v-model:value="transform.fit" style="width:100px"><a-select-option value="contain">完整包含</a-select-option><a-select-option value="cover">覆盖裁切</a-select-option></a-select><a-select v-model:value="transform.format" style="width:90px"><a-select-option value="png">PNG</a-select-option><a-select-option value="jpeg">JPG</a-select-option></a-select><a-checkbox v-model:checked="transform.transparent">透明背景</a-checkbox><a-input v-model:value="transform.name" placeholder="派生名称（可选）" /><a-button type="primary" :disabled="!selected.length" @click="batchTransform">批量生成派生版本</a-button></a-space>
    <a-alert v-if="summary" :message="summary" type="info" show-icon /><a-spin :spinning="loading"><div class="gallery"><a-card v-for="item in items" :key="item.id" size="small" @click="openDetail(item)"><a-checkbox :checked="selected.includes(item.id)" @click.stop @change="toggle(item.id)" /><img loading="lazy" :src="thumbs[item.id]" /><b>{{ item.display_name }}</b><small>{{ item.width }}×{{ item.height }} / {{ item.has_alpha ? '含透明像素' : '不透明' }}</small><small>已绑定 {{ item._count?.artVersions ?? 0 }} 个 Art Key</small></a-card></div></a-spin>
    <a-pagination :current="page" :page-size="pageSize" :total="total" @change="change" />
  </a-card>
  <a-drawer v-model:open="detailOpen" :title="detail?.display_name" width="720"><img class="preview" :src="detailPreview" /><a-space><a-button v-if="artKey" type="primary" @click="useForArt()">使用原图</a-button><a-button danger @click="archiveAsset">归档未引用原图</a-button></a-space><a-divider>派生版本</a-divider><a-list :data-source="detail?.variants ?? []"><template #renderItem="variant"><a-list-item><img class="variant" :src="variantUrls[variant.id]" /><span>{{ variant.variant_name }} {{ variant.width }}×{{ variant.height }} · {{ variant._count?.artVersions ?? 0 }} 引用</span><a-space><a-button v-if="artKey" size="small" type="primary" @click="useForArt(variant.id)">用于 Art Key</a-button><a-button size="small" danger @click="archiveVariant(variant.id)">归档</a-button></a-space></a-list-item></template></a-list></a-drawer>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { message } from 'ant-design-vue'; import { contentApi } from '../../api/content';
const route=useRoute(),router=useRouter(),artKey=computed(()=>String(route.query.artKey??'')),items=ref<any[]>([]),thumbs=ref<Record<string,string>>({}),selected=ref<string[]>([]),uploads=ref<File[]>([]),keyword=ref(''),alpha=ref<string>(),page=ref(1),pageSize=ref(24),total=ref(0),loading=ref(false),summary=ref(''),detail=ref<any>(),detailOpen=ref(false),detailPreview=ref(''),variantUrls=ref<Record<string,string>>({});
const transform=ref({size:'256',width:256,height:256,fit:'contain',format:'png',transparent:true,name:''});
async function load(){loading.value=true;try{const r=await contentApi.imageLibrary({page:page.value,pageSize:pageSize.value,keyword:keyword.value||undefined,hasAlpha:alpha.value});items.value=r.items;total.value=r.total;thumbs.value=Object.fromEntries(await Promise.all(r.items.map(async(i:any)=>[i.id,await contentApi.resourceBlobUrl(i.thumbnailUrl).catch(()=> '')])))}finally{loading.value=false}}
function stageUpload(file:File){uploads.value.push(file);return false} async function upload(){const r=await contentApi.uploadImageLibrary(uploads.value);summary.value=`上传完成：成功 ${r.succeeded??1}，失败 ${r.failed??0}，重复会复用已有原图。`;uploads.value=[];await load()}
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}function selectPage(){selected.value=[...new Set([...selected.value,...items.value.map(x=>x.id)])]}function setSize(){if(transform.value.size!=='custom'){const n=Number(transform.value.size);transform.value.width=n;transform.value.height=n}}
async function batchTransform(){const r=await contentApi.batchImageVariants({assetIds:selected.value,...transform.value});summary.value=`批量处理完成：成功 ${r.succeeded}，失败 ${r.failed}`;await load()}
async function openDetail(item:any){detail.value=await contentApi.imageLibraryDetail(item.id);detailPreview.value=await contentApi.resourceBlobUrl(detail.value.previewUrl);variantUrls.value=Object.fromEntries(await Promise.all(detail.value.variants.map(async(v:any)=>[v.id,await contentApi.resourceBlobUrl(v.thumbnailUrl)])));detailOpen.value=true}
async function useForArt(imageLibraryVariantId?:string){await contentApi.createVersionFromLibrary(artKey.value,{imageLibraryAssetId:detail.value.id,imageLibraryVariantId});message.success('已创建 Art Key 草稿版本');await router.push({path:'/content/resources',query:{artKey:artKey.value}})} async function archiveAsset(){await contentApi.archiveImageLibrary(detail.value.id);detailOpen.value=false;await load()} async function archiveVariant(id:string){await contentApi.archiveImageVariant(detail.value.id,id);await openDetail(detail.value)} function change(next:number){page.value=next;void load()} onMounted(load);
</script>
<style scoped>.toolbar{margin-bottom:12px}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px}.gallery img{display:block;width:100%;height:150px;object-fit:contain;background:#f5f5f5}.gallery b,.gallery small{display:block}.preview{max-width:100%;max-height:320px;object-fit:contain}.variant{width:64px;height:64px;object-fit:contain;margin-right:12px}</style>
